WITH op AS (SELECT id FROM operators WHERE slug='bingo-auctions')
SELECT
(SELECT json_agg(x) FROM (SELECT reason::text r, sub_reason::text sr, count(*) n, sum(amount_cents) c FROM refund_jobs, op WHERE refund_jobs.operator_id=op.id AND created_at>=now()-interval '84 days' GROUP BY 1,2 ORDER BY 4 DESC NULLS LAST LIMIT 15) x) refunds84,
(SELECT json_agg(x) FROM (SELECT version, published, payment_window_hours, pickup_window_days, refund_window_post_pickup_hours, no_show_policy, restock_fee_cents, relist_fee_cents FROM operator_policies, op WHERE operator_policies.operator_id=op.id ORDER BY version DESC LIMIT 2) x) policy,
(SELECT json_agg(x) FROM (SELECT name, city, state, pickup_slot_minutes, pickup_slot_capacity, pickup_mode, pickup_hours FROM warehouses, op WHERE warehouses.operator_id=op.id AND coalesce(active,true)) x) wh,
(SELECT json_build_object('n', count(*), 'p50_days', percentile_cont(0.5) WITHIN GROUP (ORDER BY d), 'p90_days', percentile_cont(0.9) WITHIN GROUP (ORDER BY d), 'over3d', count(*) FILTER (WHERE d>3), 'over7d', count(*) FILTER (WHERE d>7)) FROM (SELECT extract(epoch FROM p.completed_at - i.paid_at)/86400.0 d FROM pickups p JOIN invoices i ON i.id=p.invoice_id, op WHERE i.operator_id=op.id AND p.completed_at IS NOT NULL AND i.paid_at>=now()-interval '84 days') z) pickup_lag,
(SELECT json_build_object('lines', count(*), 'hammer_c', sum(il.winning_bid_cents)) FROM invoice_lots il JOIN invoices i ON i.id=il.invoice_id, op WHERE i.operator_id=op.id AND il.forfeited_at>=now()-interval '84 days') forfeits84,
(SELECT json_agg(x) FROM (SELECT coalesce(category,'none') cat, count(*) sold, sum(current_bid_cents) hammer_c FROM lots, op WHERE lots.operator_id=op.id AND winner_bidder_id IS NOT NULL AND closed_at>=now()-interval '84 days' GROUP BY 1 ORDER BY 3 DESC LIMIT 12) x) topcats,
(SELECT json_agg(x) FROM (SELECT app, kind, count(*) n FROM app_feedback GROUP BY 1,2 ORDER BY 3 DESC LIMIT 15) x) fb_kinds,
(SELECT json_build_object('total', count(*), 'pickup', count(*) FILTER (WHERE message ~* 'pick ?up'), 'ship_deliver', count(*) FILTER (WHERE message ~* 'ship|deliver'), 'fee_premium', count(*) FILTER (WHERE message ~* 'fee|premium|tax'), 'hold_extend_storage', count(*) FILTER (WHERE message ~* 'hold|extend|extension|storage|store it'), 'pallet_bulk', count(*) FILTER (WHERE message ~* 'pallet|bulk|wholesale|reseller|resale'), 'missing_damaged', count(*) FILTER (WHERE message ~* 'missing|damaged|broken|not work|wrong item'), 'alert_notify', count(*) FILTER (WHERE message ~* 'alert|notif|saved search'), 'refund', count(*) FILTER (WHERE message ~* 'refund')) FROM app_feedback WHERE app IS DISTINCT FROM 'staff') fb_kw,
(SELECT json_build_object('saved', count(*), 'notify', count(*) FILTER (WHERE notify), 'bidders', count(DISTINCT bidder_id)) FROM saved_searches) ss,
(SELECT json_build_object('rows', count(*), 'bidders', count(DISTINCT bidder_id)) FROM watchlist) wl,
(SELECT json_agg(x) FROM (SELECT extract(dow FROM ends_at AT TIME ZONE 'America/Chicago') dow, count(*) n, round(avg(extract(epoch FROM pickup_ends_at-pickup_starts_at)/86400.0),1) pickup_days FROM auctions, op WHERE auctions.operator_id=op.id AND ends_at>=now()-interval '84 days' GROUP BY 1 ORDER BY 1) x) auc_dow
